declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/commerce_v1230.php';$u=sk1230_user();$uid=(int)($u['id']??0);if($uid<1){header('Location: /login.php?next='.rawurlencode('/business-orders-v1230.php'));exit;}$msg='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();sk1230_group_set_status((int)($_POST['group_id']??0),(string)($_POST['status']??''),$uid,(int)($_POST['prep_minutes']??0),(string)($_POST['note']??''));$msg='Order status updated.';}}catch(Throwable $e){$err=$e->getMessage();}$rows=sk1230_business_orders($uid);?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Orders — ShahkotPK</title><link rel="stylesheet" href="/assets/commerce-v1230.css?v=1230"></head><body><main class="co1230"><header class="co-top"><div><a class="co-brand" href="/">← ShahkotPK</a><div class="co-kicker">SHOPKEEPER ORDER DESK</div><h1>Orders for your businesses</h1><p>Accept orders, set preparation time, mark ready, and hand delivery jobs to the ShahkotPK rider workflow.</p></div><div class="co-actions"><a href="/business-opportunities-v1200.php">Customer Opportunities</a><a href="/business-crm-v1180.php">CRM</a></div></header><?php if($msg):?><div class="notice ok"><?=sk1230_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice bad"><?=sk1230_h($err)?></div><?php endif;?><section class="panel"><div class="panel-head"><div><h2><?=count($rows)?> seller order group(s)</h2><p>Only businesses attached to your account are shown.</p></div></div><?php if(!$rows):?><div class="empty">No commerce orders for your businesses yet.</div><?php endif;?><?php foreach($rows as $r):?><article class="order-card"><header><div><b><?=sk1230_h($r['business_name'])?> · <?=sk1230_h($r['order_no'])?></b><p><?=sk1230_h($r['customer_name'])?> · <?=sk1230_h($r['customer_phone'])?> · <?=sk1230_h($r['fulfillment_type'])?></p></div><div><span class="status <?=sk1230_h($r['status'])?>"><?=sk1230_h(str_replace('_',' ',$r['status']))?></span><strong><?=sk1230_money($r['total'])?></strong></div></header><?php if($r['address_text']):?><p>📍 <?=sk1230_h($r['address_text'])?> <?=sk1230_h($r['area'])?></p><?php endif;?><?php if($r['scheduled_for']):?><p>🕒 Scheduled: <?=sk1230_h($r['scheduled_for'])?></p><?php endif;?><p>Payment: <?=sk1230_h(strtoupper($r['payment_method']))?> · <?=sk1230_h($r['payment_status'])?></p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?=sk1230_h(csrf_token())?>"><input type="hidden" name="group_id" value="<?=(int)$r['id']?>"><label>Status<select name="status"><option value="accepted">Accept</option><option value="preparing">Preparing</option><option value="ready">Ready / Packed</option><?php if($r['fulfillment_type']==='pickup'):?><option value="delivered">Picked Up / Complete</option><?php endif;?><option value="cancelled">Cancel</option></select></label><label>Preparation minutes<input type="number" name="prep_minutes" min="0" max="360" value="<?=(int)$r['prep_minutes']?>"></label><label class="wide">Status note<input name="note" maxlength="700" placeholder="Optional customer-visible progress note"></label><button class="btn primary wide">Update Order</button></form></article><?php endforeach;?></section></main></body></html>
